{
 "components": [
  {
   "id": "root",
   "component": "Column",
   "gap": 4,
   "children": [
    "title",
    "caption",
    "form"
   ]
  },
  {
   "id": "title",
   "component": "Title",
   "text": "Sign up for the workshop",
   "size": "lg"
  },
  {
   "id": "caption",
   "component": "Caption",
   "text": "Fill in your details and pick a session. All fields except the notes are required.",
   "color": "secondary"
  },
  {
   "id": "form",
   "component": "Card",
   "variant": "outline",
   "children": [
    "formBody"
   ]
  },
  {
   "id": "formBody",
   "component": "Column",
   "gap": 3,
   "children": [
    "name",
    "email",
    "session",
    "consent",
    "submitRow"
   ]
  },
  {
   "id": "name",
   "component": "TextField",
   "label": "Full name",
   "placeholder": "e.g. Ada Lovelace",
   "required": true,
   "value": {
    "@path": "/signup/name"
   },
   "checks": [
    {
     "@call": "required",
     "args": {
      "value": {
       "@path": "/signup/name"
      }
     },
     "message": "Please enter your name"
    },
    {
     "@call": "length",
     "args": {
      "value": {
       "@path": "/signup/name"
      },
      "min": 2,
      "max": 60
     },
     "message": "Name must be between 2 and 60 characters"
    }
   ]
  },
  {
   "id": "email",
   "component": "TextField",
   "label": "Email",
   "variant": "email",
   "placeholder": "you@example.com",
   "required": true,
   "value": {
    "@path": "/signup/email"
   },
   "checks": [
    {
     "@call": "email",
     "args": {
      "value": {
       "@path": "/signup/email"
      }
     },
     "message": "Please enter a valid email address"
    }
   ]
  },
  {
   "id": "session",
   "component": "Select",
   "label": "Session",
   "placeholder": "Choose a session",
   "required": true,
   "value": {
    "@path": "/signup/session"
   },
   "options": [
    {
     "value": "sat-morning",
     "label": "Saturday morning — 09:30",
     "description": "Foundations, 3 hours, 6 seats left"
    },
    {
     "value": "sat-afternoon",
     "label": "Saturday afternoon — 13:30",
     "description": "Hands-on practice, 3 hours, 12 seats left"
    },
    {
     "value": "sun-morning",
     "label": "Sunday morning — 09:30",
     "description": "Advanced topics, 3 hours, 4 seats left"
    }
   ],
   "checks": [
    {
     "@call": "required",
     "args": {
      "value": {
       "@path": "/signup/session"
      }
     },
     "message": "Please choose a session"
    }
   ]
  },
  {
   "id": "consent",
   "component": "CheckBox",
   "label": "I agree to the workshop terms and to being contacted about this event.",
   "value": {
    "@path": "/signup/consent"
   },
   "checks": [
    {
     "@call": "required",
     "args": {
      "value": {
       "@path": "/signup/consent"
      }
     },
     "message": "Please accept the terms to continue"
    }
   ]
  },
  {
   "id": "submitRow",
   "component": "Row",
   "justify": "end",
   "children": [
    "submit"
   ]
  },
  {
   "id": "submit",
   "component": "Button",
   "label": "Sign up",
   "variant": "primary",
   "submit": true,
   "onClick": {
    "event": {
     "name": "workshop.signup.submit",
     "context": {
      "name": {
       "@path": "/signup/name"
      },
      "email": {
       "@path": "/signup/email"
      },
      "session": {
       "@path": "/signup/session"
      },
      "consent": {
       "@path": "/signup/consent"
      }
     }
    }
   }
  }
 ],
 "data": {
  "signup": {
   "name": "",
   "email": "",
   "session": "",
   "consent": false
  }
 }
}

